<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="csrf-token" content="{{ csrf_token() }}">
<title>The Sounding Board | NBTX Club</title>
<style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#10100f;color:#f5ecdc;font:15px system-ui,sans-serif}header{padding:20px max(20px,calc((100vw - 1050px)/2));border-bottom:1px solid #483b2b;background:#181613}main{max-width:1050px;margin:auto;padding:30px 20px 70px}a{color:#e8c58d}h1,h2{font-family:Georgia,serif;font-weight:400}h1{font-size:clamp(32px,5vw,54px);margin:12px 0}h2{font-size:25px}.muted{color:#c8bba9}.card{border:1px solid #4b3b2a;background:#1d1b18;border-radius:12px;padding:22px;margin:15px 0}.post{cursor:pointer}.post:hover{border-color:#c9a16a}label{display:block;margin:12px 0}input,textarea,select{width:100%;display:block;margin-top:6px;padding:12px;border-radius:7px;background:#10100f;color:#fff;border:1px solid #64543e;font:inherit}button{background:#d4af72;color:#19140e;border:0;border-radius:7px;padding:12px 18px;font-weight:650;cursor:pointer}button:disabled{opacity:.5;cursor:wait}.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.actions select{width:auto;min-width:220px}.pill{display:inline-block;color:#e6c18b;border:1px solid #6e5535;border-radius:20px;padding:5px 10px;font-size:12px}.content{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}.reply{border-top:1px solid #42372a;padding:12px 0}#status{min-height:24px;color:#e9c78c}#detail[hidden],#list[hidden]{display:none}@media(max-width:600px){.card{padding:15px}}
</style></head><body>
<header><a href="{{ route('board.home') }}">← Member dashboard</a> &nbsp; · &nbsp; NBTX CLUB</header>
<main><div class="muted">MEMBER DISCUSSIONS · PRIVATE NETWORK</div><h1>The Sounding Board</h1><p class="muted">Ask your fellow business owners. Share experience. Make better decisions together.</p>
<p id="status" role="status" aria-live="polite"></p>
<div id="list">
<details class="card" id="ask-panel"><summary style="cursor:pointer;color:#e8c58d;font-weight:700">+ Ask the group a question</summary>
<form id="ask-form"><label>Question title<input name="title" required minlength="5" maxlength="180" placeholder="Should I expand my business hours?"></label>
<label>Category<select name="category" required><option>Should I or Shouldn't I?</option><option>What Do You Think?</option><option>Business Challenge</option><option>Looking for Ideas</option><option>Lessons Learned</option></select></label>
<label>Tell the group more<textarea name="body" rows="5" minlength="10" maxlength="5000" required placeholder="What's the situation, and what feedback would help?"></textarea></label><button type="submit">Post question</button></form></details>
<div class="actions"><label>Filter by category<select id="filter"><option value="">All questions</option><option>Should I or Shouldn't I?</option><option>What Do You Think?</option><option>Business Challenge</option><option>Looking for Ideas</option><option>Lessons Learned</option></select></label><button type="button" id="refresh">Refresh</button></div>
<div id="posts">Loading discussions…</div><div class="actions"><button type="button" id="more" hidden>Load more</button></div></div>
<div id="detail" hidden><button type="button" id="back">← All questions</button><article class="card" id="question"></article><section class="card"><h2>Member perspectives</h2><div id="replies"></div><form id="reply-form"><label>Add your perspective<textarea name="body" rows="4" minlength="2" maxlength="5000" required></textarea></label><button type="submit">Post response</button></form></section><section class="card" id="outcome-section" hidden><h2>What did you decide?</h2><p class="muted">Close the loop so other members can learn from your experience.</p><form id="outcome-form"><label>Your decision or update<textarea name="outcome" rows="4" minlength="5" maxlength="5000" required></textarea></label><button type="submit">Share outcome</button></form></section></div>
</main>
<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content;
const $=id=>document.getElementById(id);
const currentMemberId=@json(auth('board')->id());
let nextPage=null,activeId=null;
function status(message){$('status').textContent=message;}
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},...options});let data;try{data=await response.json();}catch{throw Error('Server returned an unexpected response ('+response.status+').');}if(!response.ok)throw Error(data.message||Object.values(data.errors||{})[0]?.[0]||'Request failed ('+response.status+').');return data;}
function run(task){Promise.resolve().then(task).catch(e=>status(e.message));}
function renderPost(p){const box=el('article',undefined,'card post');box.tabIndex=0;box.setAttribute('role','button');box.append(el('span',p.category,'pill'),el('h2',p.title),el('p','Asked by '+p.author+' · '+p.reply_count+' responses','muted'),el('p',p.body.length>260?p.body.slice(0,260)+'…':p.body,'content'));if(p.outcome)box.append(el('p','✓ Decision shared','muted'));box.onclick=()=>run(()=>openPost(p.id));box.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();box.click();}};return box;}
async function load(reset=true){status('');if(reset){$('posts').replaceChildren();nextPage='/api/discussions'+($('filter').value?'?category='+encodeURIComponent($('filter').value):'');}if(!nextPage)return;const data=await api(nextPage);if(reset&&!data.data.length)$('posts').textContent='No questions yet. Be the first to ask.';else for(const p of data.data)$('posts').append(renderPost(p));nextPage=data.next_page_url;if(nextPage){const u=new URL(nextPage,location.origin);nextPage=u.pathname+u.search;}$('more').hidden=!nextPage;}
async function openPost(id){status('');activeId=id;const data=await api('/api/discussions/'+id);$('list').hidden=true;$('detail').hidden=false;const p=data.discussion;$('question').replaceChildren(el('span',p.category,'pill'),el('h2',p.title),el('p','Asked by '+p.author,'muted'),el('p',p.body,'content'));if(p.outcome)$('question').append(el('h2','What happened next'),el('p',p.outcome,'content'));$('replies').replaceChildren();for(const r of data.replies){const row=el('div',undefined,'reply');row.append(el('strong',r.author),el('p',r.body,'content'));$('replies').append(row);}if(!data.replies.length)$('replies').textContent='No responses yet. Share your perspective.';$('outcome-section').hidden=p.member_id!==currentMemberId||!!p.outcome;history.replaceState(null,'','#question-'+id);window.scrollTo({top:0,behavior:'smooth'});}
$('back').onclick=()=>{activeId=null;$('detail').hidden=true;$('list').hidden=false;history.replaceState(null,'',location.pathname);run(()=>load());};
$('refresh').onclick=()=>run(()=>load());$('filter').onchange=()=>run(()=>load());$('more').onclick=()=>run(()=>load(false));
async function submit(form,url,after){const button=form.querySelector('button[type=submit]');button.disabled=true;status('Saving…');try{const body=Object.fromEntries(new FormData(form));const data=await api(url,{method:'POST',body:JSON.stringify(body)});form.reset();status('Saved successfully.');await after(data);}finally{button.disabled=false;}}
$('ask-form').onsubmit=e=>{e.preventDefault();run(()=>submit(e.target,'/api/discussions',async d=>{$('ask-panel').open=false;await load();await openPost(d.id);}));};
$('reply-form').onsubmit=e=>{e.preventDefault();run(()=>submit(e.target,'/api/discussions/'+activeId+'/replies',()=>openPost(activeId)));};
$('outcome-form').onsubmit=e=>{e.preventDefault();run(()=>submit(e.target,'/api/discussions/'+activeId+'/outcome',()=>openPost(activeId)));};
const hash=location.hash.match(/^#question-(\d+)$/);if(hash)run(()=>openPost(Number(hash[1])));else run(()=>load());
</script></body></html>
